CREATE DATABASE IF NOT EXISTS llumi
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_general_ci;

USE llumi;

CREATE TABLE centros (
  id_centro int(11) NOT NULL,
  nombre varchar(255) NOT NULL,
  direccion varchar(255) NOT NULL,
  telefono varchar(15) NOT NULL,
  email_contacto varchar(255) NOT NULL,
  localidad varchar(100) NOT NULL,
  regimen varchar(100) NOT NULL,
  contrasena varchar(255) NOT NULL DEFAULT md5(nombre),
  first_login tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (id_centro)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

INSERT INTO centros VALUES
  (1,'IES Galileo','Calle Luna 45, Madrid','912345678','contacto@galileo.es','GalileoLandia','pubc.','4e68ae6a158304a56308b4df047d35b9',1),
  (2,'Colegio Newton','Av. del Saber 12, Sevilla','954123456','direccion@newton.edu','NewtonLandia','priv.','a96a381620608d9b264ec6d2636270f7',1);

CREATE TABLE denuncias (
  id_denuncia int(11) NOT NULL AUTO_INCREMENT,
  id_usuario int(11) NOT NULL,
  id_centro int(11) NOT NULL,
  fecha_denuncia timestamp NULL DEFAULT current_timestamp(),
  tipo_acoso varchar(255) NOT NULL,
  descripcion text NOT NULL,
  evidencias text DEFAULT NULL,
  es_testigo varchar(20) NOT NULL,
  nombre_victima varchar(255) DEFAULT NULL,
  relacion_victima varchar(255) DEFAULT NULL,
  nombre_acosador varchar(255) DEFAULT NULL,
  testigos varchar(20) DEFAULT NULL,
  nombre_testigo_extra varchar(255) DEFAULT NULL,
  intervencion_docente varchar(20) DEFAULT NULL,
  nombre_docente varchar(255) DEFAULT NULL,
  estado enum('pendiente','en_progreso','resuelta','en_observacion','rechazada') NOT NULL,
  fecha_resolucion timestamp NULL DEFAULT NULL,
  PRIMARY KEY (id_denuncia),
  KEY id_usuario (id_usuario),
  KEY id_centro (id_centro),
  CONSTRAINT denuncias_ibfk_1 FOREIGN KEY (id_usuario) REFERENCES usuarios(id_usuario),
  CONSTRAINT denuncias_ibfk_2 FOREIGN KEY (id_centro) REFERENCES centros(id_centro)
) ENGINE=InnoDB AUTO_INCREMENT=236 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE recursos (
  id_recurso int(11) NOT NULL AUTO_INCREMENT,
  titulo varchar(255) DEFAULT NULL,
  tipo enum('noticia','artículo','video','audio','otros','podcast') NOT NULL,
  contenido text DEFAULT NULL,
  fecha_publicacion timestamp NULL DEFAULT current_timestamp(),
  url varchar(255) DEFAULT NULL,
  img text DEFAULT NULL,
  destacada tinyint(4) DEFAULT NULL,
  id_centro int(11) NOT NULL,
  PRIMARY KEY (id_recurso),
  KEY recursos_centros_FK (id_centro),
  CONSTRAINT recursos_centros_FK FOREIGN KEY (id_centro) REFERENCES centros(id_centro) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=171 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

INSERT INTO recursos VALUES (28,'El Teléfono de la Esperanza de Baleares atiende a jóvenes con crisis suicidas: \"Un cuarto de los casos muestran esas ideas\"','noticia','En 2024, el Teléfono de la Esperanza de Baleares atendió a jóvenes a través de su nuevo \"Chat de la Esperanza\", donde uno de cada cuatro mostró ideas suicidas. La mayoría de estos jóvenes, de entre 13 y 25 años, enfrentaban crisis emocionales como rupturas sentimentales, acoso escolar o conflictos familiares, y muchos pedían ayuda por autolesiones.El servicio de chat atendió 164 jóvenes, con un tiempo medio de respuesta de 45 minutos, mucho más largo que las llamadas telefónicas, que duran 12 minutos. Además de las crisis emocionales, los jóvenes mencionaron problemas como la...','2025-04-08 13:13:05','https://www.cope.es/emisoras/illes-balears/baleares/mallorca/noticias/telefono-esperanza-baleares-atiende-jovenes-crisis-suicidas-cuarto-casos-muestran-ideas-20250408_3129620.html','https://imagenes.cope.es/files/og_thumbnail/uploads/2024/07/07/668a2b36dcb88.jpeg',1,1)
